rss.channel:
{{ .Repo.Title | xmlEscape }}
{{ if .URL }}{{ .URL | safeURL | xmlEscape }}/repoview/latest-feed.xml{{ else }}latest-feed.xml{{ end }}
Latest packages for {{ .Repo.Title | xmlEscape }}
{{ now | rssTime }}
RepoView-Go
{{ range .Latest }}


  {{ if $.URL }}{{ $.URL | safeURL | xmlEscape }}/repoview/{{ end }}{{ .Filename | xmlEscape }}+{{ if .Epoch }}{{ .Epoch | xmlEscape }}{{ else }}0{{ end }}:{{ .VersionRelease | xmlEscape }}.{{ .Arch | xmlEscape }}
  {{ if $.URL }}{{ $.URL | safeURL | xmlEscape }}/repoview/{{ end }}{{ .Filename | xmlEscape }}
  {{ .TimeBuild | rssTime }}
  Update: {{ .Name | xmlEscape }}-{{ .VersionRelease | xmlEscape }}

    <p>
      <strong>Package:</strong> {{ .Name | cdataHTML }}<br/>
      <strong>Summary:</strong> {{ .Summary | cdataHTML }}
    </p>
    <p>
      <strong>Description:</strong><br/>
      {{ .Description | cdataHTML }}
    </p>
    <h3>Changes:</h3>
    <table border="0" cellpadding="0" cellspacing="5">
    {{ range .AllVersions }}
      <tr>
        <td valign="top"><a href="{{ if $.Repo.PackageBaseURL }}{{ $.Repo.PackageBaseURL | safeURL | cdataHTML }}/{{ else if $.URL }}{{ $.URL | safeURL | cdataHTML }}/{{ else }}../{{ end }}{{ .LocationHref | safeURL | cdataHTML }}">{{ .Name | cdataHTML }}-{{ .VersionRelease | cdataHTML }}.{{ .Arch | cdataHTML }}</a>
          [<span style="white-space: nowrap">{{ .SizePackage | humanSize | cdataHTML }}</span>]</td>
        {{ if .Changelog }}
        <td valign="top">
          <strong>Changelog</strong>
          by <span>{{ .Changelog.Author | cdataHTML }} ({{ .Changelog.Date | ymd }})</span>:
          <pre style="margin: 0pt 0pt 5pt 5pt">{{ .Changelog.Changelog | cdataHTML }}</pre>
        </td>
        {{ else }}
        <td valign="top">
          <em>(no changelog entry)</em>
        </td>
        {{ end }}
      </tr>
    {{ end }}
    </table>


{{ end }}
